text:
Caveman mode: **full**

---

3 parts: class component (required for error boundary), fallback UI, error logging.

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

// ── Types ──────────────────────────────────────────────────────────────────
interface Props {
  children: ReactNode;
  fallback?: ReactNode;                          // optional custom fallback
  onError?: (error: Error, info: ErrorInfo) => void; // optional external logger
}

interface State {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

// ── Logger (swap for Sentry/Datadog/etc) ───────────────────────────────────
function logError(error: Error, info: ErrorInfo): void {
  console.error("ErrorBoundary caught:", {
    message: error.message,
    stack: error.stack,
    componentStack: info.componentStack,
    timestamp: new Date().toISOString(),
  });
}

// ── Component ──────────────────────────────────────────────────────────────
class ErrorBoundary extends Component<Props, State> {
  state: State = {
    hasError: false,
    error: null,
    errorInfo: null,
  };

  // Fires during render phase — update state to show fallback
  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  // Fires after render — side effects (logging) live here
  componentDidCatch(error: Error, info: ErrorInfo): void {
    logError(error, info);
    this.props.onError?.(error, info);           // forward to caller if provided
    this.setState({ errorInfo: info });
  }

  handleRetry = (): void => {
    this.setState({ hasError: false, error: null, errorInfo: null });
  };

  render(): ReactNode {
    const { hasError, error, errorInfo } = this.state;
    const { children, fallback } = this.props;

    if (!hasError) return children;

    // Custom fallback provided — render it
    if (fallback) return fallback;

    // Default fallback UI
    return (
      <div role="alert" style={styles.container}>
        <h2 style={styles.title}>Something went wrong</h2>

        <p style={styles.message}>
          {error?.message ?? "An unexpected error occurred."}
        </p>

        {/* Stack trace — dev only */}
        {process.env.NODE_ENV === "development" && errorInfo && (
          <details style={styles.details}>
            <summary>Stack trace</summary>
            <pre style={styles.pre}>
              {error?.stack}
              {"\n\nComponent stack:"}
              {errorInfo.componentStack}
            </pre>
          </details>
        )}

        <button onClick={this.handleRetry} style={styles.button}>
          Try again
        </button>
      </div>
    );
  }
}

// ── Styles (inline — swap for CSS modules/Tailwind as needed) ──────────────
const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: "2rem",
    margin: "2rem auto",
    maxWidth: "600px",
    border: "1px solid #f87171",
    borderRadius: "8px",
    backgroundColor: "#fff1f2",
    fontFamily: "sans-serif",
  },
  title: { color: "#b91c1c", marginTop: 0 },
  message: { color: "#374151" },
  details: { marginTop: "1rem" },
  pre: {
    fontSize: "0.75rem",
    overflowX: "auto",
    background: "#f3f4f6",
    padding: "1rem",
    borderRadius: "4px",
  },
  button: {
    marginTop: "1rem",
    padding: "0.5rem 1.25rem",
    background: "#b91c1c",
    color: "#fff",
    border: "none",
    borderRadius: "4px",
    cursor: "pointer",
    fontSize: "1rem",
  },
};

export default ErrorBoundary;
```

---

**Usage**

```tsx
// Wrap any subtree
<ErrorBoundary onError={(err, info) => sentryCapture(err, info)}>
  <Dashboard />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary fallback={<MyCustomError />}>
  <PaymentForm />
</ErrorBoundary>
```

---

**Key points**

| Thing | Why |
|---|---|
| `getDerivedStateFromError` | Static — runs during render, no side effects, just flips state |
| `componentDidCatch` | Runs after render — safe for logging, external calls |
| Retry resets state | Child remounts fresh — works if error was transient |
| Stack trace dev-only | No internal details leak to prod |
| `role="alert"` | Screen readers announce error immediately |

---

**Gotchas**

- Error boundaries catch render/lifecycle errors only. Event handler errors need `try/catch` inside handler.
- Retry remount child — if error from bad prop/data, fix source first or retry loop forever.
- One boundary per critical section. Don't wrap whole app in one — too coarse.
